import manifest from './images.json';

export const image = (filename) => /^https?:\/\//.test(filename) ? filename : `/images/homeafar/${encodeURIComponent(filename)}`;
export const slugOf = (file) => file.replace(/\.[^.]+$/, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const webp = (slug, width) => `/images/homeafar/${slug}-${width}.webp`;
export const reducedMotion = () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Responsive WebP props (srcset built from images.json, generated by the image pipeline).
export const photoProps = (file, sizes = '100vw') => {
  if (/^https?:\/\//.test(file)) return { src: file, sizes };
  const slug = slugOf(file);
  const meta = manifest[slug];
  const widths = meta.w;
  const mid = widths[Math.min(2, widths.length - 1)];
  return { src: webp(slug, mid), srcSet: widths.map((w) => `${webp(slug, w)} ${w}w`).join(', '), sizes, width: meta.width, height: meta.height };
};

export const Photo = ({ file, alt, sizes, eager = false, ...rest }) => (
  <img {...photoProps(file, sizes)} alt={alt} loading={eager ? 'eager' : 'lazy'} decoding="async" {...rest} />
);
